[3090]={["aftermath"]="Nartok warned that power did not guarantee acceptance. Thrall permitted warlocks among his kin, but foolish use of their abilities could still prove fatal.",["atomIDs"]={"3090:description:1-53","3090:description:58-163","3090:description:165-234","3090:description:236-282","3090:objective:1-86"},["endingAtomIDs"]={"3090:completion:1-37","3090:completion:39-62","3090:completion:64-176","3090:completion:178-345","3090:completion:347-370","3090:completion:372-442","3090:completion:447-495"},["opening"]="Gornek usually avoided warlocks, but he passed on a parchment from the newly appointed trainer Nartok. The message directed its reader inside the Den.",["pending"]="{actor} planned to read the Tainted Parchment and speak to Nartok inside the Den.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} read the Tainted Parchment and met Nartok.",["sourceClassMask"]="256",["sourceHash"]="220a0e045436bc1aa3b5ede1895b154ed3d8158693da35908dd1124de2b9a8d0",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
