[3100]={["aftermath"]="Llane offered training at any hour and urged familiarity with the land. Even Northshire's relative safety left its people in need of a warrior's help.",["atomIDs"]={"3100:description:1-94","3100:description:96-182","3100:description:184-271","3100:objective:1-70"},["endingAtomIDs"]={"3100:completion:1-104","3100:completion:106-131","3100:completion:136-354","3100:completion:356-365"},["opening"]="Marshal McBride had been asked to deliver a letter after the work at the kobold camps. Llane's insignia identified the local warrior trainer as its sender.",["pending"]="{actor} meant to read the Simple Letter and speak to Llane Beshere in Northshire Abbey.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} read the Simple Letter and met Llane Beshere.",["sourceClassMask"]="1",["sourceHash"]="9647a2416fa5e1ff20d5fc87def0a875b352a1a54be1688a11c741a21d8b3159",["sourceMapID"]="?",["sourceRaceMask"]="1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
